// GENERATED AUTOMATICALLY, DO NOT EDIT
let list = ""; // empty array base64 encoded

list = JSON.parse(window.atob(list));

const baseurl = "";
const from = window.location.pathname
  .toLowerCase()
  .replace(new RegExp(`^/*${baseurl}`), "")
  .replace(/^(\/+)/, "");

const to = list.find((entry) => entry?.from === from)?.to;

console.info({ from, to });

function setStatus(nodes) {
  const status = document.getElementById("status");
  if (!status) return;
  status.replaceChildren(...nodes);
}

function go() {
  if (to) {
    const link = document.createElement("a");
    link.href = to;
    link.textContent = to;
    setStatus(["Redirecting you to ", link, "…"]);
    // Let the message paint, then navigate (also leaves a clickable link if nav stalls).
    setTimeout(() => {
      window.location.href = to;
    }, 50);
  } else if (from) {
    setStatus([`No redirect found for /${from}.`]);
  } else {
    setStatus(["No redirect path specified."]);
  }
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", go);
} else {
  go();
}
